import{_ as t,H as a,f as n,i as r}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"复习课（三） | 团队建设","description":"","frontmatter":{},"headers":[{"level":3,"title":"（三）团队建设","slug":"三-团队建设","link":"#三-团队建设","children":[]}],"relativePath":"技术管理实战36讲/复习课（三）-团队建设.md","filePath":"技术管理实战36讲/复习课（三）-团队建设.md","lastUpdated":1779820334000}'),s={name:"技术管理实战36讲/复习课（三）-团队建设.md"};function i(E,e,o,g,p,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="复习课-三-团队建设" tabindex="-1">复习课（三） | 团队建设 <a class="header-anchor" href="#复习课-三-团队建设" aria-label="Permalink to &quot;复习课（三） | 团队建设&quot;">​</a></h1><hr><p>继上一篇的“ <strong>管理规划</strong>”之后，接下来我们继续来复习“管理方法论”的另外一个方面： <strong>团队建设</strong>。</p><h3 id="三-团队建设" tabindex="-1">（三）团队建设 <a class="header-anchor" href="#三-团队建设" aria-label="Permalink to &quot;（三）团队建设&quot;">​</a></h3><p>如何带好团队呢？</p><p>这里依然类比“马车模型”，如何让“马队”跑得动、跑得快、跑得远呢？</p><p>可以将“马队”拆解为： <strong>“马匹个体”“马匹之间”“马队整体”</strong>。那对应地，团队也可拆解为： <strong>“员工个体”“员工个体之间”“团队整体”</strong>。类比分析后，有如下：</p><ol><li>马匹个体：力气+意愿 <strong>VS</strong> 员工个体：能力+意愿</li><li>马匹之间：阵型+节奏 <strong>VS</strong> 员工之间：分工+协作</li><li>马队整体：构成+面貌 <strong>VS</strong> 团队整体：梯队+文化</li></ol><p>所以，就可以得出如下“团队建设全透视图”，也引出 <strong>能力、激励、分工、协作、梯队</strong> 和 <strong>文化</strong> 6个维度的工作要素。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/fd237c45c16f33be24cf7c7f7e2a9fae.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/fd237c45c16f33be24cf7c7f7e2a9fae.png" alt=""></a></p><p>（来自 <a href="https://time.geekbang.org/column/article/40043" target="_blank" rel="noreferrer">第16篇《团队建设该从哪里入手？》</a>）</p><p><strong>1. 员工能力</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/03702757b348665303a7b99f93cd04ba.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/03702757b348665303a7b99f93cd04ba.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/40277" target="_blank" rel="noreferrer">第17篇《如何提升员工的个人能力？》</a></p><p><strong>2. 员工激励</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/d1896e0c723dae3a75ac418b52a6a0c1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/d1896e0c723dae3a75ac418b52a6a0c1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/7073ab548c26e541c0942727d6a77a1a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/7073ab548c26e541c0942727d6a77a1a.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/40313" target="_blank" rel="noreferrer">第18篇《如何提升员工的工作意愿和积极性？》</a></p><p><strong>3. 团队分工</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/134d017f15ca99a763b2a49b7a0dbc1f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/134d017f15ca99a763b2a49b7a0dbc1f.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/40513" target="_blank" rel="noreferrer">第19篇《如何兼顾团队分工的稳定性和灵活性？》</a></p><p><strong>4. 团队协作</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/9ba929d7b237b67ac84a4e2394a7caa3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/9ba929d7b237b67ac84a4e2394a7caa3.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/40516" target="_blank" rel="noreferrer">第20篇《有什么方法可以有效提升团队凝聚力吗？》</a></p><p><strong>5. 梯队培养</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/fa49ad2abf39eb915fc6e766ed20300b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/fa49ad2abf39eb915fc6e766ed20300b.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/40771" target="_blank" rel="noreferrer">第21篇《如何物色和培养核心人才？》</a></p><p><strong>6. 团队文化</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/84f09b2acd1c91320111b43a0529a68f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/84f09b2acd1c91320111b43a0529a68f.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/40772" target="_blank" rel="noreferrer">第22篇《如何建设团队文化，营造团队氛围？》</a></p><p><strong>7. 场景1，绩效沟通</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/543de304149f0f0f038e1e9aad44a542.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/543de304149f0f0f038e1e9aad44a542.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/40776" target="_blank" rel="noreferrer">第23篇《如何和低绩效员工谈绩效？》</a></p><p><strong>8. 场景2，团建活动</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/2987df465b7fbf23e6e2fa419caecc11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68046/2987df465b7fbf23e6e2fa419caecc11.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/40780" target="_blank" rel="noreferrer">第24篇《如何让团建活动不再“收效甚微”？》</a></p><p>至此我们就复习完了团队建设的全部6个要素： <strong>能力、激励、分工、协作、梯队</strong> 和 <strong>文化</strong>，以及相关的两个工作场景： <strong>绩效沟通</strong> 和 <strong>团建活动</strong>。详细内容也可戳文中所附的链接。</p><hr>',38)])])}const h=t(s,[["render",i]]);export{l as __pageData,h as default};
